function idleAnalyticsInit(){analytics=idleAnalyticsLoad();if(!analytics||analytics.sessionVersion!==168)resetIdleAnalytics();analytics.huntStartedAt=Date.now()}
function idleAnalyticsSettle(){if(!analytics||!analytics.huntStartedAt)return;analytics.totalHuntSeconds=Number(analytics.totalHuntSeconds||0)+Math.max(0,(Date.now()-analytics.huntStartedAt)/1000);analytics.huntStartedAt=0;idleAnalyticsSave(true)}
function idleAnalyticsRecordDrop(name){if(!analytics||!name)return;const match=String(name).match(/^(.*?)\s*[×x]\s*(\d+)$/);const qty=match?Number(match[2]):1;if(match)name=match[1];idleSocialLog('loot',{name:String(name),qty});const r=analytics.drops.find(x=>x.name===String(name));if(r)r.qty+=qty;else analytics.drops.push({name:String(name),qty});idleAnalyticsSave()}
const IDLE_SUPPLY_PRICES={'Pokéball':20,'Great Ball':50,'Super Ball':100,'Ultra Ball':200,'Premier Ball':500,'Poção 50':30,'Poção 100':50,'Poção 200':100,'Poção 30%':1000,'Poção 50% HP':3000,'Poção 100% HP':10000,'Revive':800};
const IDLE_BALLS=['Pokéball','Great Ball','Super Ball','Ultra Ball','Premier Ball',...TYPE_ORDER.map(t=>t+' Ball')];
const IDLE_MAX_ORDINARY_BALL_INDEX=4+TYPE_ORDER.length;
function idleBallRank(name){return IDLE_BALLS.indexOf(String(name||''))}
function idleNearestAvailableBall(selected,inv,minRank=0,maxRank=IDLE_BALLS.length-1){const rank=idleBallRank(selected),origin=Math.max(minRank,Math.min(maxRank,rank<0?minRank:rank));return IDLE_BALLS.map((name,index)=>({name,index,qty:Number(inv?.[name]||0)})).filter(x=>x.qty>0&&x.index>=minRank&&x.index<=maxRank).sort((a,b)=>Math.abs(a.index-origin)-Math.abs(b.index-origin)||b.index-a.index)[0]?.name||null}
function idleBallForCapture(selected,inv,shiny=false){const rank=idleBallRank(selected),floor=shiny?Math.max(0,idleBallRank(idleProgress()?.shinyBallFloor)):0,max=shiny?IDLE_BALLS.length-1:IDLE_MAX_ORDINARY_BALL_INDEX;if(rank>=floor&&rank<=max&&Number(inv?.[selected]||0)>0)return selected;return idleNearestAvailableBall(selected,inv,floor,max)}
function idleResolveHelperBall(h,key,inv,shiny=false){const selected=h[key],ball=idleBallForCapture(selected,inv,shiny);if(ball&&ball!==selected){h[key]=ball;persistIdleHelperSettings(h);notify(`${shiny?'Auto-Catch Shiny':'Auto-Catch'}: ${selected} esgotou; usando ${ball}.`)}return ball}
const IDLE_COMMON_DROP_ITEMS=new Set(['Rubber Ball','Fire Tail','Water Gem','Seed','Great Petal','Screw','Electric Rat Tail','Snowball','Ice Orb','Band Aid','Belt Of Champion','Bottle Of Poison','Bug Venom','Earth Ball','Piece Of Diglett','Straw','Giant Beak','Enchanted Gem','Psychic Spoon','Bug Gosme','Bug Antenna','Small Stone','Strange Rock','Ghost Essence','Bat Wing','Dragon Scale','Dragon Tooth','Dark Gem','Dark Ear','Piece Of Steel','Metal Hull','Cute Ball']);
const IDLE_RARE_DROP_ITEMS=new Set(['Giant Piece Of Fur','Water Pendant','Great Petal','Electric Rat Tail','Ice Orb','Belt Of Champion','Bug Venom','Piece Of Diglett','Giant Beak','Psychic Spoon','Bug Antenna','Strange Rock','Bat Wing','Dragon Tooth','Dark Ear','Metal Hull','Cute Ball']);
const IDLE_SELLABLE_ITEMS=new Set(['Rubber Ball','Fire Tail','Water Gem','Seed','Screw','Snowball','Band Aid','Bottle Of Poison','Earth Ball','Straw','Enchanted Gem','Bug Gosme','Ghost Essence','Dragon Scale','Dark Gem','Piece Of Steel']);
let helperTick=0,potionReady=0,analyzerTick=0;
const IDLE_HELPER_PREFS_KEY='psy_idle.helper_preferences.v1';
function persistIdleHelperSettings(h){try{W.localStorage?.setItem(IDLE_HELPER_PREFS_KEY,JSON.stringify(h))}catch(e){}queueIdleSave()}
function idleHelperSettings(){const x=idleProgress(),defaults={potion:true,revive:true,catchNormal:true,catchShiny:true,potionName:'auto',threshold:50,ball:'Pokéball',shinyBall:'Ultra Ball',names:''};let local=null;try{const raw=W.localStorage?.getItem(IDLE_HELPER_PREFS_KEY);if(raw!==null)local=JSON.parse(raw)}catch(e){}if(!x.helper||typeof x.helper!=='object')x.helper={...defaults};else x.helper={...defaults,...x.helper};if(local&&typeof local==='object')x.helper={...x.helper,...local};else{try{W.localStorage?.setItem(IDLE_HELPER_PREFS_KEY,JSON.stringify(x.helper))}catch(e){}queueIdleSave()}return x.helper}
function idleSupplyUsed(name){if(!analytics)return;analytics.supply=analytics.supply||{};analytics.supply[name]=(analytics.supply[name]||0)+1;idleAnalyticsSave()}
function resetIdleAnalytics(){analytics={sessionVersion:168,drops:[],captured:0,captureValue:0,defeated:0,shinies:0,megas:0,xp:0,gold:0,supply:{},totalHuntSeconds:0,huntStartedAt:Date.now()};idleAnalyticsSave(true)}
