function idleItemArtwork(n){const items=W.PSY_ITEMS,u=items?.url?.(n)||items?.localUrl?.(n)||'';return u?`<img src="${idleSafeText(u)}" alt="${idleSafeText(n)}">`:'<span>◆</span>'}
function idleAnalyzerData(){const sec=Math.max(0,(analytics.totalHuntSeconds||0)+(Date.now()-(analytics.huntStartedAt||Date.now()))/1000),supply=Object.entries(analytics.supply||{}).reduce((sum,[n,q])=>sum+(IDLE_SUPPLY_PRICES[n]||0)*q,0),loot=Number(analytics.gold||0)+analytics.drops.reduce((sum,d)=>sum+d.qty*idleSellValue(d.name),0),balance=loot+Number(analytics.captureValue||0)-supply;return{sec,supply,loot,balance,rate:sec>0?3600/sec:0}}
function idleAnalyticsViewValues(){const a=analytics,v=idleAnalyzerData(),fmt=n=>Math.floor(Number(n)||0).toLocaleString('pt-BR'),money=n=>(n<0?'-$':'$')+fmt(Math.abs(n)),s=a.supply||{},balls=IDLE_BALLS.reduce((sum,n)=>sum+(s[n]||0),0),potions=Object.entries(s).filter(([n])=>n.startsWith('Poção')).reduce((sum,[,q])=>sum+q,0),count=a.drops.reduce((sum,d)=>sum+Number(d.qty||0),0);return{a,v,fmt,money,s,balls,potions,count,dropSignature:JSON.stringify(a.drops.map(d=>[d.name,d.qty]))}}
function idleAnalyticsDropMarkup(a,fmt,money){return a.drops.map(d=>`<div class="ir-drop">${idleItemArtwork(d.name)}<span>${idleSafeText(d.name)}</span><em>×${fmt(d.qty)}</em><b>${money(d.qty*idleSellValue(d.name))}</b></div>`).join('')||'<p>Nenhum drop nesta sessão.</p>'}
function refreshIdleAnalyticsPanel(){const o=D.getElementById('psy-ir-analytics-overlay'),panel=o?.querySelector('.ir-ref-panel');if(!panel)return;if(!analytics)idleAnalyticsInit();const {a,v,fmt,money,s,balls,potions,count,dropSignature}=idleAnalyticsViewValues(),setValue=(key,text)=>{const el=o.querySelector(`[data-an-value="${key}"]`);if(el&&el.textContent!==String(text))el.textContent=String(text)},setLabel=(key,text)=>{const el=o.querySelector(`[data-an-label="${key}"]`);if(el&&el.textContent!==String(text))el.textContent=String(text)};setValue('defeated',fmt(a.defeated||0));setValue('time',`${Math.floor(v.sec/60)}m ${Math.floor(v.sec%60)}s`);setValue('xp',fmt(a.xp||0));setValue('captured',fmt(a.captured||0));setLabel('captured',`Capturados (+${money(a.captureValue||0)})`);setValue('loot',money(v.loot));setLabel('loot',`Loot (${fmt(count)} itens)`);setValue('supply','-'+money(v.supply));setLabel('supply',`Supply (${balls} bolas · ${potions} potions${s.Revive?' · '+s.Revive+' revives':''})`);const balance=o.querySelector('[data-an-balance]');if(balance){balance.textContent=`${v.balance>=0?'+':''}${money(v.balance)}`;balance.classList.toggle('ir-bad',v.balance<0);balance.classList.toggle('ir-good',v.balance>=0)}const rates=o.querySelectorAll('[data-an-rate]');if(rates[0])rates[0].textContent=`📈 ${money(v.balance*v.rate)}/h`;if(rates[1])rates[1].textContent=`✨ ${fmt((a.xp||0)*v.rate)} XP/h`;if(rates[2])rates[2].textContent=`⚔ ${fmt((a.defeated||0)*v.rate)}/h`;const drops=o.querySelector('.ir-drops');if(drops&&drops.dataset.signature!==dropSignature){const scroll=drops.scrollTop;drops.innerHTML=idleAnalyticsDropMarkup(a,fmt,money);drops.dataset.signature=dropSignature;drops.scrollTop=scroll}}
function openAnalytics(){idlePanelStyles();if(!analytics)idleAnalyticsInit();const o=D.getElementById('psy-ir-analytics-overlay');if(!o)return;if(!o.dataset.analyticsMounted||!o.querySelector('.ir-ref-panel')){const metric=(key,icon,value,label,cls='')=>`<div class="ir-metric"><span>${icon}</span><div><b data-an-value="${key}" class="${cls}">${value}</b><small data-an-label="${key}">${label}</small></div></div>`,{a,v,fmt,money,s,balls,potions,count,dropSignature}=idleAnalyticsViewValues();o.innerHTML=`<section class="ir-ref-panel"><header class="ir-ref-head"><strong>▥ Hunt Analyzer</strong><div><button id="ir-an-reset" aria-label="Zerar sessão">♲</button><button id="ir-an-close" aria-label="Fechar">×</button></div></header><div class="ir-ref-content"><p class="ir-session">· sessão atual</p><div class="ir-metrics">${metric('defeated','⚔️',fmt(a.defeated||0),'Derrotados')}${metric('time','⏱️',`${Math.floor(v.sec/60)}m ${Math.floor(v.sec%60)}s`,'Tempo na hunt')}${metric('xp','✨',fmt(a.xp||0),'XP ganha','ir-xp')}${metric('captured','🔴',fmt(a.captured||0),`Capturados (+${money(a.captureValue||0)})`)}${metric('loot','💰',money(v.loot),`Loot (${fmt(count)} itens)`,'ir-good')}${metric('supply','🛒','-'+money(v.supply),`Supply (${balls} bolas · ${potions} potions${s.Revive?' · '+s.Revive+' revives':''})`,'ir-bad')}</div><div class="ir-balance"><span>Saldo (Loot + Capturas − Supply)</span><strong data-an-balance class="${v.balance<0?'ir-bad':'ir-good'}">${v.balance>=0?'+':''}${money(v.balance)}</strong></div><div class="ir-rates"><span class="ir-good" data-an-rate="gold">📈 ${money(v.balance*v.rate)}/h</span><span class="ir-xp" data-an-rate="xp">✨ ${fmt((a.xp||0)*v.rate)} XP/h</span><span data-an-rate="kills">⚔ ${fmt((a.defeated||0)*v.rate)}/h</span></div><label class="ir-market" title="Esta versão offline usa os preços da loja; mercado entre jogadores indisponível."><input type="checkbox" disabled> Considerar preço dos itens no Mercado</label><h3 class="ir-drop-title">DROPS DA SESSÃO</h3><div class="ir-drops" data-signature="${idleSafeText(dropSignature)}">${idleAnalyticsDropMarkup(a,fmt,money)}</div><button class="ir-log" id="ir-an-log">VER LOG DE CAPTURAS</button><p class="ir-foot">Valores em preço de NPC. Os contadores zeram ao trocar de hunt.</p></div></section>`;o.dataset.analyticsMounted='1';o.querySelector('#ir-an-close').onclick=()=>o.style.display='none';o.querySelector('#ir-an-reset').onclick=()=>{resetIdleAnalytics();refreshIdleAnalyticsPanel()};o.querySelector('#ir-an-log').onclick=()=>{o.style.display='none';openIdleSuite('captures')}}o.style.display='flex';refreshIdleAnalyticsPanel()}
function openIdleHelper(){idlePanelStyles();let o=D.getElementById('psy-ir-helper');if(!o){o=D.createElement('section');o.id='psy-ir-helper';o.className='ir-ref-panel';screen.appendChild(o)}const h=idleHelperSettings(),inv=idleWallet().drops,esc=idleSafeText,toggle=(key,icon,title,hint='')=>`<label class="ir-helper-toggle"><input type="checkbox" data-helper="${key}" ${h[key]?'checked':''}>${icon}<b>${title}</b><small>${hint}</small></label>`,balls=key=>`<div class="ir-balls">${IDLE_BALLS.filter(n=>(inv[n]||0)>0||h[key]===n).map(n=>`<button data-ball-key="${key}" data-ball="${esc(n)}" title="${esc(n)}" class="${h[key]===n?'selected':''}">${idleItemArtwork(n)}<b data-ball-count="${esc(n)}">${Number(inv[n]||0).toLocaleString('pt-BR')}</b></button>`).join('')}</div>`;o.innerHTML=`<header class="ir-ref-head"><strong>⚙ Auto-Helper</strong><button id="ir-helper-close" aria-label="Fechar">×</button></header><div class="ir-ref-content">${toggle('potion',idleItemArtwork('Poção 50'),'Auto-Potion')}<div class="ir-helper-options"><label>Potion: <select data-helper="potionName">${['auto',...Object.keys(IDLE_SUPPLY_PRICES).filter(n=>n.startsWith('Poção'))].map(n=>`<option value="${esc(n)}" ${h.potionName===n?'selected':''}>${n==='auto'?'Automático (melhor)':n}</option>`).join('')}</select></label><label>Curar com HP ≤ <select data-helper="threshold">${[10,25,50,75,90].map(n=>`<option ${h.threshold==n?'selected':''}>${n}</option>`).join('')}</select>%</label></div>${toggle('revive',idleItemArtwork('Revive'),'Auto-Revive','usa Revive ao desmaiar')}${toggle('catchNormal','🔴','Auto-Catch','Pokémon normais')}<div class="ir-helper-options">Pokébola:${balls('ball')}</div>${toggle('catchShiny','✨','Auto-Catch Shiny','Pokémon shiny')}<div class="ir-helper-options">Pokébola (shiny):${balls('shinyBall')}</div><div class="ir-helper-options" style="margin-top:14px">Nomes (separe por vírgula):<input type="text" data-helper="names" value="${esc(h.names)}" placeholder="ex: charizard, gyarados"><p>Campo em branco = capturar todos. O filtro vale pros dois modos.</p></div></div>`;o.style.display='block';o.onfocusin=()=>keys.clear();o.querySelector('#ir-helper-close').onclick=()=>o.style.display='none';o.querySelectorAll('[data-helper]').forEach(el=>el.onchange=()=>{h[el.dataset.helper]=el.type==='checkbox'?el.checked:el.dataset.helper==='threshold'?Number(el.value):el.value;persistIdleHelperSettings(h)});o.querySelectorAll('[data-ball]').forEach(el=>el.onclick=()=>{h[el.dataset.ballKey]=el.dataset.ball;persistIdleHelperSettings(h);openIdleHelper()})}
function idlePotionHealAmount(name,maxHp){const hp=Math.max(1,Number(maxHp)||1);if(name==='Poção 30%')return hp*.3;if(name==='Poção 50% HP')return hp*.5;if(name==='Poção 100% HP')return hp;return Math.max(0,Number(String(name||'').split(' ')[1]||0))}
function idleApplyPotion(name){if(!player||player.dead)return 0;const maxHp=Math.max(1,Number(player.maxHp)||1),before=clamp(Number(player.hp)||0,0,maxHp),after=clamp(before+idlePotionHealAmount(name,maxHp),0,maxHp);if(after<=before)return 0;player.hp=after;if(player.poke)player.poke.hp=after;persistIdlePokemonHp();const text=D.getElementById('psy-ir-hptxt'),bar=D.getElementById('psy-ir-hpbar');if(text)text.textContent=`❤ ${Math.ceil(after)} / ${Math.ceil(maxHp)}`;if(bar)bar.style.width=clamp(after/maxHp*100,0,100)+'%';queueIdleSave();return after-before}
function updateIdleHelper(dt){helperTick-=dt;potionReady=Math.max(0,potionReady-dt);if(helperTick>0||!player)return;helperTick=.5;const h=idleHelperSettings(),inv=idleWallet().drops;if(player.dead){if(h.revive&&inv.Revive>0){inv.Revive--;idleSupplyUsed('Revive');const maxHp=Math.max(1,Number(player.maxHp)||1),revivedHp=clamp(maxHp*.5,1,maxHp);player.dead=0;player.hp=revivedHp;if(player.poke)player.poke.hp=revivedHp;player.poison=0;potionReady=0;persistIdlePokemonHp();queueIdleSave()}return}const maxHp=Math.max(1,Number(player.maxHp)||1),currentHp=clamp(Number(player.hp)||0,0,maxHp),threshold=Number(h.threshold??50);if(h.potion&&potionReady<=0&&currentHp/maxHp*100<=threshold){const missing=maxHp-currentHp,heal=n=>idlePotionHealAmount(n,maxHp),effective=n=>Math.min(missing,heal(n)),choices=Object.keys(IDLE_SUPPLY_PRICES).filter(n=>n.startsWith('Poção')&&inv[n]>0&&(h.potionName==='auto'||n===h.potionName)).sort((a,b)=>effective(b)-effective(a)||heal(a)-heal(b)),n=choices[0];if(n&&idleApplyPotion(n)>0){inv[n]--;idleHuntSfx('heal',{channel:'heal',volume:.22,cooldown:1300});potionReady=8;idleSupplyUsed(n);queueIdleSave()}}const names=String(h.names||'').toLocaleLowerCase('pt-BR').split(',').map(n=>n.trim()).filter(Boolean);const normalBall=h.catchNormal?idleResolveHelperBall(h,'ball',inv,false):null,shinyBall=h.catchShiny?idleResolveHelperBall(h,'shinyBall',inv,true):null;const target=corpses.find(e=>!e.dead&&!e.capturing&&!e.captureAttempted&&(e.shiny?!!shinyBall:!!normalBall)&&(!names.length||names.includes(e.name.toLocaleLowerCase('pt-BR')))&&inv[e.shiny?shinyBall:normalBall]>0);if(target)startIdleCapture(target,target.shiny?shinyBall:normalBall);const panel=D.getElementById('psy-ir-helper');if(panel?.style.display==='block')panel.querySelectorAll('[data-ball-count]').forEach(el=>el.textContent=Number(inv[el.dataset.ballCount]||0).toLocaleString('pt-BR'))}
const IDLE_AUTO_KEY='psy_idle.auto.v1';function loadIdleAuto(){try{const saved=W.localStorage?.getItem(IDLE_AUTO_KEY);return saved===null?true:saved!=='0'}catch(e){return true}}function saveIdleAuto(){try{W.localStorage?.setItem(IDLE_AUTO_KEY,auto?'1':'0')}catch(e){}}
function syncIdleAutoButton(){const b=D.getElementById('psy-ir-auto');if(!b)return;b.classList.toggle('on',auto);b.textContent=auto?'🤖 AUTO ON':'🕹 AUTO OFF'}
function loadIdleAfkSession(){try{return JSON.parse(W.localStorage?.getItem(IDLE_SESSION_KEY)||'null')}catch(e){return null}}
function saveIdleAfkSession(){try{W.localStorage?.setItem(IDLE_SESSION_KEY,JSON.stringify({lastSeen:Date.now(),active:!!running&&!!auto,auto:!!auto,map:currentMapKey}))}catch(e){}}
let idleFarmCheckpointTimer=0,idleVisibilityPaused=false,idleFarmNoticeAt=0;
function reportIdleFarmFailure(error){
 const now=Date.now(),code=String(error?.message||'');
 console.warn('[PSY IDLE] falha no farm online/offline',error);
 if(now-idleFarmNoticeAt<90000)return;
 idleFarmNoticeAt=now;
 const loginRequired=/auth_required|invalid_session|idle_farm_login_required|idle_auth_bridge_unavailable/i.test(code);
 notify(loginRequired?'🔒 Para caçar com o jogo fechado, conecte sua conta online do Idle e deixe AUTO ligado.':'⚠️ Não foi possível salvar a caça online. Verifique a conexão e mantenha o Idle aberto até aparecer a confirmação.',5200);
}
function presentIdleAfkSummary(){
 try{return W.PsyIdleAfkSummary?.displayPending(PSTATE(),{onSeen:()=>{saveIdleCharacter();queueIdleSave()}})||false}
 catch(error){console.warn('[PSY IDLE] falha ao mostrar resumo AFK',error);return false}
}
function applyIdleOfflineClaim(report,requestId=''){
 if(!report||!report.ok)return false;
 const p=PSTATE();p.meta=p.meta||{};
 const claimId=String(requestId||''),applied=Array.isArray(p.meta.psyIdleFarmClaimReceipts)?p.meta.psyIdleFarmClaimReceipts:[];
 if(claimId&&applied.includes(claimId)){const saved=saveIdleCharacter();presentIdleAfkSummary();return saved}
 const xp=Math.max(0,Math.floor(Number(report.xp_awarded)||0)),gold=Math.max(0,Math.floor(Number(report.gold_awarded)||0)),kills=Math.max(0,Math.floor(Number(report.kills_awarded)||0)),drops=report.drops&&typeof report.drops==='object'?report.drops:{};
 const mon=activeIdlePokemon();if(mon&&xp)addIdlePokemonXp(mon,xp);if(kills)idleRecordOfflineKills(report.species_id,kills);
 if(xp)addIdlePlayerXp(xp);
 const w=idleWallet();w.gold=Number(w.gold||0)+gold;
 for(const [name,qty] of Object.entries(drops))if(Number(qty)>0)w.drops[name]=Number(w.drops[name]||0)+Number(qty);
 if(kills){p.meta.worldIdleAfkSeconds=Number(p.meta.worldIdleAfkSeconds||0)+Number(report.elapsed_seconds||0);p.meta.worldIdleAfkGold=Number(p.meta.worldIdleAfkGold||0)+gold;p.meta.worldIdleAfkKills=Number(p.meta.worldIdleAfkKills||0)+kills;if(analytics){analytics.defeated+=kills;analytics.gold+=gold;analytics.xp+=xp;for(const [name,qty] of Object.entries(drops)){const row=analytics.drops.find(x=>x.name===name);if(row)row.qty+=Number(qty);else analytics.drops.push({name,qty:Number(qty)})}idleAnalyticsSave()}}
 if(kills||xp||gold||Object.values(drops).some(qty=>Number(qty)>0)){
  const mapKey=String(report.claimed_map_key||currentMapKey||''),active=activeIdlePokemon();
  W.PsyIdleAfkSummary?.record(p,report,claimId,{
   mapName:MAPS[mapKey]?.name||currentMap?.name||mapKey||'Caçada AFK',
   speciesName:report.species_id?getPokemonName(Number(report.species_id)):'',
   pokemonName:active?.name||getPokemonName(Number(active?.id)||0)||'Pokémon ativo'
  });
 }
 if(claimId){p.meta.psyIdleFarmClaimReceipts=[...applied,claimId].slice(-24)}
 if(!saveIdleCharacter())return false;
 if(kills)queueIdleSave();
 presentIdleAfkSummary();
 return true;
}
async function idleFarmAuthContext(){
 const clientFactory=W.PsyIdleSocial?.client;
 if(typeof clientFactory!=='function')throw new Error('idle_auth_bridge_unavailable');
 const c=await clientFactory();if(!c?.auth)throw new Error('idle_auth_bridge_unavailable');
 const auth=await c.auth.getSession();if(auth.error)throw auth.error;
 const token=auth.data?.session?.access_token;if(!token)throw new Error('idle_farm_login_required');
 const userId=String(auth.data?.user?.id||auth.data?.session?.user?.id||'');
 if(!userId)throw new Error('idle_farm_login_required');
 return{client:c,token,userId};
}
function idleRequestId(){return W.crypto?.randomUUID?.()||'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)})}
function idleWait(ms){return new Promise(resolve=>setTimeout(resolve,Math.max(0,ms)))}
async function idleOfflinePost(action,payload,requestId=idleRequestId(),ctx=null){
 const context=ctx||await idleFarmAuthContext();
 const response=await fetch('/api/idle-hunt-farm',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+context.token},body:JSON.stringify({action,request_id:requestId,...payload}),keepalive:true});
 const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(String(body.error||'online_error'));return body;
}
let idleFarmClaimQueue=Promise.resolve();
async function performIdleFarmClaim(payload){
 const ctx=await idleFarmAuthContext(),storageKey=IDLE_SESSION_KEY+':farm-claim-v1:'+ctx.userId;
 const clearPending=requestId=>{try{const row=JSON.parse(W.localStorage?.getItem(storageKey)||'null');if(row?.request_id===requestId)W.localStorage.removeItem(storageKey)}catch(_){}};
 const settle=async row=>{const report=await idleOfflinePost('claim',row.payload,row.request_id,ctx);if(!applyIdleOfflineClaim(report,row.request_id))throw new Error('idle_claim_local_save_failed');clearPending(row.request_id);return report};
 let pending=null;try{pending=JSON.parse(W.localStorage?.getItem(storageKey)||'null')}catch(_){}
 if(pending?.request_id&&pending?.payload)await settle(pending);
 const row={request_id:idleRequestId(),payload:{...payload}};
 try{W.localStorage?.setItem(storageKey,JSON.stringify(row))}catch(e){throw new Error('idle_claim_local_storage_unavailable')}
 return settle(row);
}
function requestIdleFarmClaim(payload){
 const work=idleFarmClaimQueue.catch(()=>null).then(()=>performIdleFarmClaim(payload));
 idleFarmClaimQueue=work.catch(()=>null);return work;
}
function idleFarmCombatStats(){const mon=player?.poke||activeIdlePokemon();return{attacker_atk:Math.max(1,Math.floor(Number(player?.atk||mon?.atk||35))),attacker_level:Math.max(1,Math.floor(Number(player?.poke?.level||mon?.level||1)))}}
async function resumeIdleAfkSession(autoFarm=!!auto){try{return await requestIdleFarmClaim({map_key:currentMapKey,auto_farm:!!autoFarm,nickname:PSTATE().name||'Treinador',...idleFarmCombatStats()})}catch(e){reportIdleFarmFailure(e);return null}}
async function checkpointIdleFarm(action='checkpoint'){try{if(action==='claim'){return await requestIdleFarmClaim({map_key:currentMapKey,auto_farm:!!auto,nickname:PSTATE().name||'Treinador',...idleFarmCombatStats()})}return await idleOfflinePost('checkpoint',{map_key:currentMapKey,auto_farm:!!auto,nickname:PSTATE().name||'Treinador',...idleFarmCombatStats()})}catch(e){reportIdleFarmFailure(e);return null}}
function startIdleFarmCheckpoints(){if(idleFarmCheckpointTimer)clearInterval(idleFarmCheckpointTimer);idleFarmCheckpointTimer=setInterval(()=>{if(running&&D.visibilityState==='visible')checkpointIdleFarm('checkpoint')},15000)}

function PSTATE(){return loadIdleCharacter()}
let idleHuntClaimQueue=Promise.resolve(),idleOnlineBallNotice=0;
async function idleOnlinePost(action,payload,requestId=idleRequestId()){
 const c=await W.PsyIdleSocial?.client?.();if(!c)return null;const auth=await c.auth.getSession();if(auth.error)throw auth.error;const token=auth.data?.session?.access_token;if(!token)return null;
 let response,lastError;for(let attempt=0;attempt<2;attempt++){try{response=await fetch('/api/idle-hunt',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({action,request_id:requestId,...payload})});break}catch(e){lastError=e;if(attempt===0)await idleWait(350)}}
 if(!response)throw lastError||new Error('online_unavailable');const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(String(body.error||'online_error'));return body;
}
function requestIdleHuntTicket(enemy){
 if(!W.PsyIdleSocial?.client)return;const requestId=idleRequestId();enemy.idleOnlineTicketPromise=idleOnlinePost('start',{map_key:currentMapKey,nickname:PSTATE().name||'Treinador'},requestId).then(data=>{
  const ticket=data?.ticket;if(!ticket)return null;enemy.idleOnlineTicket=ticket;enemy.idleOnlineTicketAt=Date.now();enemy.tier=ticket.tier;const local=(W.RARITIES||[]).find(r=>r.n===ticket.rarity?.n);enemy.rarity={...(local||{}),n:ticket.rarity?.n||'Lixo',mult:Number(ticket.rarity?.mult||1),bonus:0};enemy.shiny=false;return ticket;
 }).catch(error=>{enemy.idleOnlineTicketError=String(error?.message||'online_error');return null});
}
function recordIdleOnlineVictory(enemy){
 if(!enemy||enemy.raidBoss||enemy.idleOnlineVictoryPromise)return null;const requestId=enemy.idleOnlineVictoryRequestId||idleRequestId();enemy.idleOnlineVictoryRequestId=requestId;
 const work=idleHuntClaimQueue.then(async()=>{
  const ticket=enemy.idleOnlineTicket||await enemy.idleOnlineTicketPromise;if(!ticket?.id)return null;
  const wait=Math.max(0,Number(ticket.min_duration_ms||0)-(Date.now()-Number(enemy.idleOnlineTicketAt||Date.now()))+150);if(wait)await idleWait(wait);
  for(let attempt=0;attempt<5;attempt++)try{const result=await idleOnlinePost('victory',{ticket_id:ticket.id},requestId);enemy.idleOnlineVictoryResult=result;const drop=result?.drop?` • ${result.drop}`:'';notify(`Cofre online do Idle: +${Number(result?.gold_awarded||0)} Gold • +${Number(result?.xp_awarded||0)} XP${drop}`);return result}catch(error){const code=String(error?.message||'');if(code==='battle_too_fast'){await idleWait(900);continue}if(code==='reward_cooldown'){await idleWait(3200);continue}enemy.idleOnlineVictoryError=code;return null}
  return null;
 });idleHuntClaimQueue=work.catch(()=>null);enemy.idleOnlineVictoryPromise=work;return work;
}
function recordIdleOnlineCapture(enemy,ball){
 if(!enemy||enemy.idleOnlineCapturePromise)return null;
 const source=enemy.idleHuntSource||enemy;
 enemy.idleOnlineCapturePromise=Promise.resolve(source.idleOnlineVictoryPromise).then(async won=>{
  const ticket=source.idleOnlineTicket||await source.idleOnlineTicketPromise;if(!won||!ticket?.id)return null;const requestId=enemy.idleOnlineCaptureRequestId||(enemy.idleOnlineCaptureRequestId=idleRequestId());const result=await idleOnlinePost('capture',{ticket_id:ticket.id,ball},requestId);
  notify(result.captured?`Cofre online do Idle: ${result.species_name} capturado para o Market.`:`Cofre online do Idle: a tentativa de ${result.species_name} falhou; sua captura local segue separada.`);return result;
 }).catch(error=>{const code=String(error?.message||'');if(code==='online_ball_unavailable'&&Date.now()-idleOnlineBallNotice>15000){idleOnlineBallNotice=Date.now();notify('A Ball local foi usada; o cofre online não tem essa Ball.')}return null});return enemy.idleOnlineCapturePromise;
}
function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
function dist2(a,b){const x=a.x-b.x,y=a.y-b.y;return x*x+y*y}
function hypot(x,y){return Math.sqrt(x*x+y*y)||1}
function seeded(seed){let s=seed>>>0;return()=>((s=(s*1664525+1013904223)>>>0)/4294967296)}
function notify(m){try{W.notif?.(m,2300)}catch(e){}}
function typeEff(atk,def){try{return typeof W.getEffectiveness==='function'?W.getEffectiveness(atk,def):1}catch(e){return 1}}
function pokeTypes(p){try{return typeof W.psyResolvePokemonTypes==='function'?W.psyResolvePokemonTypes(p):(p?.type||'Normal')}catch(e){return p?.type||'Normal'}}
function pokeImg(p){try{return W.getRealSprite?.(p)||`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${p.id}.png`}catch(e){return`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${p.id}.png`}}
function pokeAnimUrls(p,animated=true){const id=Math.max(1,Number(p?.id||1)),sh=!!(p?.shiny||p?.isShiny),png=`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${sh?'shiny/':''}${id}.png`,gif=sh?`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/versions/generation-v/black-white/animated/shiny/${id}.gif`:`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/versions/generation-v/black-white/animated/${id}.gif`;return animated?[gif,pokeImg(p),png]:[png]}
function image(urls){const list=Array.isArray(urls)?urls:[urls],im=new Image();let i=0;im.decoding='async';im.onload=()=>{};im.onerror=()=>{i++;if(i<list.length)im.src=list[i]};im.src=list[i];return im}
function spritePoke(p,animated=true){const key=`poke:${animated?'anim':'static'}:${Number(p?.id||1)}:${p?.form||p?.forme||''}:${p?.shiny||p?.isShiny?'s':'n'}`;const cached=spriteCache.get(key);if(cached)return cached;const im=image(pokeAnimUrls(p,animated));spriteCache.set(key,im);if(spriteCache.size>64)spriteCache.delete(spriteCache.keys().next().value);return im}
// V1.2 — colisão corporal separada da navegação.
const ENEMY_BODY_BOX={10:[29,34,-17],13:[28,34,-17],16:[30,35,-18],19:[30,34,-17],43:[31,37,-18],46:[33,36,-17],48:[34,38,-18],69:[29,38,-19],84:[32,40,-20],102:[39,32,-15]};
function configureBodyBox(e,isPlayer=false){if(isPlayer){e.navR=PLAYER_NAV_R;e.r=e.navR;e.hitRx=40;e.hitRy=46;e.hitOy=-20}else{const b=ENEMY_BODY_BOX[Number(e.id)]||[31,36,-18];e.navR=26;e.r=e.navR;e.hitRx=b[0];e.hitRy=b[1];e.hitOy=b[2]}e.hitOx=0;return e}
function bodyBox(e){return{x:e.x+(e.hitOx||0),y:e.y+(e.hitOy||0),rx:Math.max(8,Number(e.hitRx||e.r||24)),ry:Math.max(8,Number(e.hitRy||e.r||24))}}
function pointHitsBody(x,y,r,e){const h=bodyBox(e),rx=h.rx+r,ry=h.ry+r,dx=x-h.x,dy=y-h.y;return(dx*dx)/(rx*rx)+(dy*dy)/(ry*ry)<=1}
function aoeTouchesBody(x,y,r,e){const h=bodyBox(e),dx=h.x-x,dy=h.y-y,rr=r+Math.max(h.rx,h.ry)*.72;return dx*dx+dy*dy<=rr*rr}
function bodyEdgeDistance(a,b){const ha=bodyBox(a),hb=bodyBox(b),dx=hb.x-ha.x,dy=hb.y-ha.y,d=Math.sqrt(dx*dx+dy*dy)||1,ux=Math.abs(dx/d),uy=Math.abs(dy/d),ra=Math.sqrt((ha.rx*ux)**2+(ha.ry*uy)**2),rb=Math.sqrt((hb.rx*ux)**2+(hb.ry*uy)**2);return Math.max(0,d-ra-rb)}
function separatePokemon(){const live=enemies.filter(e=>!e.dead&&!e.downed);for(let i=0;i<live.length;i++)for(let j=i+1;j<live.length;j++){const a=live[i],b=live[j];if(a.raidBoss||b.raidBoss)continue;const dx=b.x-a.x,dy=b.y-a.y,d=Math.sqrt(dx*dx+dy*dy)||.001,min=(a.navR||20)+(b.navR||20)+3;if(d<min){const push=(min-d)*.5,ux=dx/d,uy=dy/d,ax=a.x-ux*push,ay=a.y-uy*push,bx=b.x+ux*push,by=b.y+uy*push;if(!idleBodyBlocked(a,ax,ay)){a.x=ax;a.y=ay}if(!idleBodyBlocked(b,bx,by)){b.x=bx;b.y=by}}}}
