function idlePlayerPanel(){const q=idlePlayerProfile(),next=Math.max(0,q.xpNext-q.xp),poke=activeIdlePokemon(),rate=Number(analytics?.trainerXp||0)/Math.max(1,(analytics?.totalHuntSeconds||0)+(Date.now()-(analytics?.huntStartedAt||Date.now()))/1000)*60,mins=rate>0?Math.ceil(next/rate):null;let need=next;const chart=Array.from({length:5},(_,i)=>{const t=rate>0?need/rate:null,width=rate>0?Math.max(5,Math.min(100,100/(1+i*.32))):5,row={label:i===0?'Próximo nível':`+${i+1} níveis`,min:t};need+=idleTrainerXpNext(q.level+i+1);return `<div style="display:grid;grid-template-columns:90px 1fr 65px;align-items:center;gap:7px;margin:5px 0;font-size:9px"><span>${row.label}</span><span class="psy-ir-task-bar"><i style="width:${width}%"></i></span><b>${row.min===null?'—':row.min<60?`${Math.max(1,Math.ceil(row.min))} min`:`${(row.min/60).toFixed(1)} h`}</b></div>`}).join('');return `<div class="psy-ir-suite-grid"><article class="psy-ir-suite-card"><h3>🧑 Jogador • Psy Idle Lv.${q.level}</h3><p>XP ${q.xp.toLocaleString('pt-BR')} / ${q.xpNext.toLocaleString('pt-BR')}</p><div class="psy-ir-task-bar"><i style="width:${Math.min(100,q.xp/q.xpNext*100)}%"></i></div><p>Faltam <b>${next.toLocaleString('pt-BR')} XP</b> para o próximo nível.</p><small>Estimativa na hunt atual, calculada pelo XP/minuto real desta sessão${idleBoostActive('xp')?' com o boost atual':''}:</small>${chart}<p><small>Próximo nível: ${mins===null?'coletando dados de XP da sessão':`aprox. ${mins} minutos`}</small></p></article><article class="psy-ir-suite-card"><h3>🐾 Pokémon ativo</h3><p>${idleSafeText(poke?.name||'Sem Pokémon')} • Lv.${Number(poke?.level||1)}</p><p>XP ${Number(poke?.exp||0).toLocaleString('pt-BR')} / ${Number(poke?.maxExp||100).toLocaleString('pt-BR')}</p><small>O jogador e cada Pokémon têm níveis e barras de XP separados.</small><p>Boosts ativos: ${['xp','capture','loot','gold'].map(k=>{const end=Number(PSTATE()?.meta?.psyIdleBuffs?.[k]||0),left=Math.max(0,end-Date.now());return left?`${k==='xp'?'XP +50%':k==='capture'?'Captura ×2':k==='gold'?'Gold +50%':'Loot +50%'} ${Math.ceil(left/60000)} min`:''}).filter(Boolean).join(' • ')||'nenhum'}</p></article></div>`}
function idleBreedingParentPreview(id){
 const p=PSTATE(),parents=[...(p?.team||[]),...(p?.box||[])].filter(m=>Number(m?.id)===Number(id)&&!m.shiny&&!m.isMega).slice(0,2);
 if(parents.length<2)return'<small>Selecione uma espécie com dois Pokémon normais para ver os IVs herdados.</small>';
 return'<div style="display:grid;gap:6px;margin:8px 0"><b>IVs e Nature dos pais</b>'+parents.map((m,i)=>{const g=W.PsyIdleGenetics?.ensure(m),v=g?.ivs||{};return'<small>Genitor '+(i+1)+' • '+idleSafeText(m.name||getPokemonName(m.id))+' • Nature: '+idleSafeText(W.PsyIdleGenetics?.natureLabel(m)||g?.nature?.name||'Neutra')+' • HP '+v.hp+' / ATK '+v.atk+' / DEF '+v.def+' / SPD '+v.spd+'</small>'}).join('')+'<small>O filhote herda pelo menos o maior IV de cada atributo entre os pais.</small></div>';
}
function idleBreedPanel(){
 const q=idlePlayerProfile(),p=PSTATE(),mons=[...(p?.team||[]),...(p?.box||[])].filter(m=>m&&!m.shiny&&!m.isMega),counts={};
 for(const m of mons)counts[m.id]=(counts[m.id]||0)+1;
 const eligible=mons.filter(m=>counts[m.id]>=2),candy=Number(idleWallet().drops['Love Candy']||0),bound=Number(idleWallet().boundLoveCandy||0),gold=Number(idleWallet().gold||0),opened=q.level>=30,ids=[...new Set(eligible.map(m=>Number(m.id)))],firstId=ids[0]||0;
 return'<article class="psy-ir-suite-card"><h3>🧬 Breeding</h3><p>'+(opened?'Desbloqueado':'🔒 Desbloqueia no nível 30 do jogador Psy Idle')+' • Love Candy: <b>'+candy+'</b> ('+bound+' vinculados por captura) • Gold: <b>'+gold.toLocaleString('pt-BR')+' / 500.000</b></p><p>Use 1 Love Candy e 500.000 Gold Psy Idle e dois Pokémon normais da mesma espécie. Os pais permanecem no time/box; o filhote entra na Box. Breeding é a única fonte de qualidade acima de Lêndea neste modo.</p>'+(opened?'<label>Espécie dos pais　<select id="psy-ir-breed-id">'+(ids.map(id=>'<option value="'+id+'">'+idleSafeText(getPokemonName(id))+' ×'+counts[id]+'</option>').join('')||'<option value="">Precisa de duas cópias normais da mesma espécie</option>')+'</select></label><div id="psy-ir-breed-parents">'+idleBreedingParentPreview(firstId)+'</div><button id="psy-ir-breed-go" '+(!eligible.length||!candy||gold<500000?'disabled':'')+'>💝 BREEDAR (500.000 Gold + 1 Love Candy)</button>':'')+'<small>Capturas de qualidade superior a Lêndea seguem bloqueadas; o filhote pode herdar a raridade dos pais ou avançar um degrau, respeitando a sequência do PSYWORLD.</small></article>';
}
function idleCapturePanel(){const x=idleProgress(),entries=Object.entries(x?.ballUsage||{}).sort((a,b)=>Number(b[1])-Number(a[1])),tot=entries.reduce((a,[,n])=>a+Number(n||0),0),logs=(x?.captureLog||[]).slice(0,12);return `<section class="psy-ir-capture-book"><div class="psy-ir-capture-intro"><span class="psy-ir-capture-mark">◉</span><div><small>DIÁRIO DE CAMPO • PSY IDLE</small><h3>Registro de Captura</h3><p>Histórico de Pokébolas usadas e resultados recentes.</p></div><strong>${tot.toLocaleString('pt-BR')}<small>BOLAS USADAS</small></strong></div><div class="psy-ir-capture-summary">${entries.map(([n,c])=>`<div class="psy-ir-capture-ball"><span>●</span><b>${idleSafeText(n)}</b><strong>×${Number(c).toLocaleString('pt-BR')}</strong></div>`).join('')||'<div class="psy-ir-capture-empty">Nenhuma Pokébola usada neste modo ainda.</div>'}</div><div class="psy-ir-capture-log-head"><div><small>ÚLTIMAS TENTATIVAS</small><h4>Registro recente</h4></div><span>até 12 lançamentos</span></div><div class="psy-ir-capture-log">${logs.map(r=>`<article class="psy-ir-capture-entry"><img src="${escapeMapText(pokeImg({id:r.id}))}" loading="lazy"><div><b>${escapeMapText(getPokemonName(r.id))}</b><small>#${String(r.id).padStart(3,'0')} • ${idleSafeText(r.ball)} • ${new Date(r.at).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}</small></div><span class="${r.success?'success':r.resolved?'miss':'pending'}">${r.success?'CAPTURADO':r.resolved?'NÃO CAPTUROU':'AGUARDANDO'}</span></article>`).join('')||'<div class="psy-ir-capture-empty">As tentativas de captura vão aparecer aqui.</div>'}</div></section>`}
function idleCalendarReward(day){if(day%10===0)return{kind:'coin',qty:1};const balls=[3,7,11,15,19,23,27],i=balls.indexOf(day);if(i>=0)return{kind:'item',item:'Ultra Ball',qty:[100,100,110,110,120,120,140][i]};if([1,4,6,9,12,14,17,18,22,24,26,29].includes(day))return{kind:'randomBoost',qty:1};return{kind:'box',qty:1}}
function idleRewardLabel(r){return r.kind==='item'?`${r.qty} ${r.item}`:r.kind==='starterBox'?'Caixa Shiny de Inicial (9 regiões)':r.kind==='regionBox'?'Caixa Regional '+r.region:r.kind==='gold'?`${r.qty.toLocaleString('pt-BR')} Gold`:r.kind==='coin'?`${r.qty} Psycoin`:r.kind==='box'?'Caixa Misteriosa':r.kind==='randomBoost'?'Boost aleatório • 1h':`${{xp:'XP',loot:'Loot',gold:'Gold',capture:'Captura'}[r.key]} ${r.key==='capture'?'×2':'+50%'} • 1h`}
function idleRewardArt(r){if(r.kind==='item')return idleItemArtwork(r.item);const file=r.kind==='coin'?'comet-shard':r.kind==='gold'?'amulet-coin':r.kind==='starterBox'?'pack-sss':r.kind==='box'?'pack-rare':'boost-stone';return `<img src="assets/items/${file}.png" alt="" style="width:28px;height:28px;object-fit:contain;image-rendering:pixelated">`}
function idleRewardMarkup(rewards){return rewards.map(r=>`<span style="display:inline-flex;align-items:center;gap:6px;margin:4px;font-size:11px">${idleRewardArt(r).replace('<img ','<img style="width:28px;height:28px;object-fit:contain;image-rendering:pixelated" ')}<span>${idleSafeText(idleRewardLabel(r))}</span></span>`).join('')}
function buyIdlePassPlus(product){const pass=idleProgress()?.pass;if(!pass||Number(pass.xp||0)<100000)return notify('A loja Pass+ libera ao concluir o nível 100.');const cost=product.kind==='ball'?100:500;if(Number(pass.plusPoints||0)<cost)return notify('Você ainda não tem Pontos Pass+ suficientes.');pass.plusPoints-=cost;if(product.kind==='ball')idleGrantReward({kind:'item',item:product.type+' Ball',qty:30});else idleGrantReward({kind:'regionBox',region:product.region});queueIdleSave();notify(product.kind==='ball'?'Troca concluída: 30 '+(TYPE_PT[product.type]||product.type)+' Balls.':'Caixa Regional '+product.region+' adicionada à bag.');openIdleSuite('pass',true)}
function idleGrantReward(r){const p=PSTATE(),w=idleWallet();p.meta=p.meta||{};if(r.kind==='randomBoost')r={kind:'boost',key:['xp','loot','gold','capture'][Math.floor(Math.random()*4)]};if(r.kind==='box'){const pool=[{kind:'gold',qty:2000},{kind:'gold',qty:5000},{kind:'gold',qty:8000},{kind:'item',item:'Ultra Ball',qty:30},{kind:'item',item:'Revive',qty:5},{kind:'item',item:'Poção 200',qty:10},{kind:'item',item:TYPE_ORDER[Math.floor(Math.random()*TYPE_ORDER.length)]+' Ball',qty:10}];r=pool[Math.floor(Math.random()*pool.length)]}if(r.kind==='item')w.drops[r.item]=Number(w.drops[r.item]||0)+r.qty;else if(r.kind==='starterBox')w.drops['Caixa Shiny de Inicial (9 regiões)']=Number(w.drops['Caixa Shiny de Inicial (9 regiões)']||0)+1;else if(r.kind==='regionBox'){const key='Caixa Regional '+r.region;w.drops[key]=Number(w.drops[key]||0)+1}else if(r.kind==='gold')w.gold=Number(w.gold||0)+r.qty;else if(r.kind==='coin')p.psycoin=Number(p.psycoin||0)+r.qty;else if(r.kind==='boost'){const b=p.meta.psyIdleBuffs||(p.meta.psyIdleBuffs={});b[r.key]=Math.max(Date.now(),Number(b[r.key]||0))+3600000}return idleRewardLabel(r)}
function idleClaimCalendar(){const p=PSTATE();p.meta=p.meta||{};const now=new Date(),today=[now.getFullYear(),now.getMonth()+1,now.getDate()].join('-'),c=p.meta.psyIdleCalendar||(p.meta.psyIdleCalendar={count:0,lastDate:''});if(c.lastDate===today)return false;const day=c.count%30+1;c.lastDate=today;c.count++;const label=idleGrantReward(idleCalendarReward(day));c.lastReward=label;queueIdleSave();notify('Check-in: '+label);return true}
function idlePassRewards(n,kind){const type=TYPE_ORDER[(n-1)%TYPE_ORDER.length],r=[{kind:'item',item:type+' Ball',qty:12+Math.floor(n/10)}];if(n%10===0)r.push({kind:'gold',qty:n*150},{kind:'item',item:n%20===0?'Rare Card Pack':'Revive',qty:n%20===0?1:3+Math.floor(n/10)});if(n%5===0)r.push({kind:'boost',key:['xp','loot','capture','gold'][(n/5-1)%4]},{kind:'item',item:'Boost Stone',qty:2});else if(n%4===0)r.push({kind:'item',item:n%8===0?'Mega Stone Fragment':'Shiny Stone',qty:1+Math.floor(n/25)});else if(n%3===0)r.push({kind:'gold',qty:n*100});if(kind==='premium'){if(n%2===0)r.push({kind:'item',item:'Great Ball',qty:15+Math.floor(n/5)});if(n%5===0)r.push({kind:'item',item:'Shiny Stone',qty:1},{kind:'item',item:'Mega Stone Fragment',qty:1});if(n%10===0)r.push({kind:'item',item:'Epic Card Pack',qty:1})}if(n===100&&kind==='free')r.push({kind:'starterBox'});return r}
function idleBallMultiplier(ball,target){const type=ball.replace(/ Ball$/,'');if(TYPE_ORDER.includes(type))return getPokemonTypes(target.id).includes(type)?6:1;return({'Pokéball':1,'Great Ball':1.5,'Super Ball':2,'Ultra Ball':3,'Premier Ball':1.5})[ball]||1}
function idleDailyPanel(){const p=PSTATE(),c=p.meta?.psyIdleCalendar||{count:0},now=new Date(),today=[now.getFullYear(),now.getMonth()+1,now.getDate()].join('-'),claimed=c.lastDate===today,day=claimed?((c.count-1)%30)+1:c.count%30+1;return `<section class="psy-ir-calendar-panel"><h3>Calendário de Aventuras</h3><p>30 check-ins • um resgate por dia • progresso mantido se perder um dia</p><div class="psy-ir-calendar-grid" style="grid-template-columns:repeat(5,minmax(0,1fr));max-height:340px;overflow:auto">${Array.from({length:30},(_,i)=>{const d=i+1,r=idleCalendarReward(d);return `<div class="psy-ir-calendar-day ${d===day?'today':''}" style="min-height:85px;padding:6px"><b>Dia ${d}</b>${idleRewardArt(r)}<small style="font-size:10px">${idleSafeText(idleRewardLabel(r))}</small>${d<day||d===day&&claimed?'✓':''}</div>`}).join('')}</div><p>Hoje: ${idleSafeText(claimed?c.lastReward:idleRewardLabel(idleCalendarReward(day)))}</p><small>Caixas: 2.000–8.000 Gold, 30 Ultra Balls, 10 Balls elementais, 5 Revives ou 10 Poções 200. Bônus de 1h: XP, Loot ou Gold +50%, sorteados no resgate.</small><div class="psy-ir-calendar-footer"><button id="psy-ir-checkin" ${claimed?'disabled':''}>${claimed?'✓ RESGATADO':'RESGATAR DIA '+day}</button></div></section>`}

let idlePassPage=0;
