function openIdleRaidPanel(){const overlay=D.getElementById('psy-ir-suite-overlay'),root=D.getElementById('psy-ir-suite-content'),title=D.getElementById('psy-ir-suite-title');if(!overlay||!root)return;overlay.dataset.idleTab='raid';title.textContent='Raids de Boss';root.dataset.raidSlot=String(RAID_RULES.schedule(Date.now()).slot);root.innerHTML=idleRaidPanel();overlay.style.display='flex';root.querySelectorAll('[data-raid-mode]').forEach(b=>b.onclick=()=>startIdleRaid(b.dataset.raidMode))}
function raidSpawnPoint(){const dirs=[0,.52,-.52,1.05,-1.05,1.57,-1.57,2.1,-2.1,2.62,-2.62,3.14];for(let r=205;r<=325;r+=20)for(const a of dirs){const x=clamp(player.x+Math.cos(a)*(player.facing<0?-r:r),90,WORLD_W-90),y=clamp(player.y+Math.sin(a)*r,90,WORLD_H-90);if(!collides(x,y,58))return{x,y}}return{x:clamp(player.x+220,90,WORLD_W-90),y:clamp(player.y,90,WORLD_H-90)}}
