let idleRankingRequestSeq=0;
async function loadIdleRanking(root,seq){const isCurrent=()=>root?.dataset?.idleTab==='ranking'&&root.dataset.rankingRequest===String(seq);if(!root)return;idleRankingSetStatus(root,'Carregando ranking global…');try{const response=await idleLeaderboardPost({action:'board',request_id:idleRequestId(),nickname:String(PSTATE()?.name||'Treinador').slice(0,24)});if(!isCurrent())return;if(!response?.periods&&!response?.leaderboards)throw new Error('invalid_leaderboard_response');idleRankingRenderBoard(root,response);idleRankingSetStatus(root,`Ranking atualizado · ${idleSafeText(response.timezone||'UTC')} · classificação por ${idleSafeText(response.score_metric||'XP de Hunt')}.`)}catch(error){if(!isCurrent())return;idleRankingSetStatus(root,idleRankingErrorMessage(error),true,true)}}
async function claimIdleRankingPrize(root,period,button,seq){if(!['daily','weekly','monthly'].includes(period)||button?.disabled)return;button.disabled=true;button.textContent='Resgatando…';idleRankingSetStatus(root,'Confirmando a recompensa com o servidor…');try{const result=await idleLeaderboardPost({action:'claim',request_id:idleRequestId(),period,nickname:String(PSTATE()?.name||'Treinador').slice(0,24)});if(root?.dataset?.rankingRequest!==String(seq))return;if(result?.claimed){const amount=Number(result.reward_gold??result.gold_awarded??0);idleRankingSetStatus(root,amount>0?`Prêmio confirmado: ${amount.toLocaleString('pt-BR')} Gold creditados à sua conta.`:'Recompensa confirmada pelo servidor.')}else idleRankingSetStatus(root,'Este período não tem uma recompensa disponível para sua conta.');await loadIdleRanking(root,seq)}catch(error){if(root?.dataset?.rankingRequest!==String(seq))return;idleRankingSetStatus(root,idleRankingErrorMessage(error),true,true);button.disabled=false;button.textContent='Tentar resgatar novamente'}}
function openIdleRanking(root){const seq=++idleRankingRequestSeq;root.dataset.rankingRequest=String(seq);if(!root.dataset.rankingClickBound){root.dataset.rankingClickBound='1';root.addEventListener('click',event=>{const button=event.target?.closest?.('[data-rank-action]');if(!button)return;const action=button.dataset.rankAction;if(action==='refresh'){loadIdleRanking(root,Number(root.dataset.rankingRequest));return}if(action==='claim')claimIdleRankingPrize(root,String(button.dataset.rankPeriod||''),button,Number(root.dataset.rankingRequest))})}loadIdleRanking(root,seq)}
function idleRankingPanel(){const x=idleProgress(),p=PSTATE(),me=[{score:idlePlayerProfile().level,label:'Nível do treinador'},{score:Object.values(x?.captures||{}).reduce((a,b)=>a+Number(b||0),0),label:'Capturas neste modo'},{score:Object.values(x?.kills||{}).reduce((a,b)=>a+Number(b||0),0),label:'Abates neste modo'}];return `<article class="psy-ir-suite-card"><h3>🏆 Ranking global do Psy Idle</h3><p>Hunts diárias, semanais e mensais · classificação por XP de Hunt · período em UTC.</p><div data-ranking-status role="status" aria-live="polite">Carregando ranking global…</div><button type="button" data-rank-action="refresh" hidden>Atualizar ranking</button><div data-ranking-board style="margin-top:10px">Os resultados aparecerão aqui quando o servidor responder.</div><section class="psy-ir-suite-card" style="margin-top:12px"><h4>Seu resumo neste modo</h4><p>${idleSafeText(p?.name||'Jogador')}</p>${me.map(row=>`<div>${row.label}: <b>${Number(row.score).toLocaleString('pt-BR')}</b></div>`).join('')}</section><p style="font-size:10px;color:#9bb3c6">O resumo pessoal permanece disponível mesmo sem login ou conexão. Prêmios globais são validados e creditados pelo servidor.</p></article>`}
