function renderMoveHud(){const c=D.getElementById('psy-ir-moves');if(!c||!player)return;c.innerHTML=player.moves.map((m,i)=>`<button type="button" class="psy-ir-move psy-ir-skill-only" data-move="${i}" style="border-color:${COLORS[m.type]||'#31526a'};--skill-glow:${COLORS[m.type]||'#67e8f9'}" title="Toque para usar ${m.name}"><b>✦ ${m.name}</b><small>${TYPE_PT[m.type]||m.type} • Habilidade Nv.${m.elementTier} • ${m.aoe?`Área ${Math.round(m.radius/48*10)/10} SQM`:`Alvo único • alcance ${Math.round(m.range/48*10)/10} SQM`}</small><i class="cd"></i></button>`).join('');c.querySelectorAll('[data-move]').forEach(el=>el.addEventListener('click',()=>requestIdleSkill(Number(el.dataset.move))))}
