function render(){const w=cv.clientWidth,h=cv.clientHeight;ctx.save();ctx.fillStyle='#285d37';ctx.fillRect(0,0,w,h);ctx.scale(CAMERA_ZOOM,CAMERA_ZOOM);drawGround();ctx.save();ctx.translate(-cam.x,-cam.y);for(const d of decorations){const pad=(d.t==='moss'?75:59)*d.scale+8;if(worldVisible(d.x,d.y,pad))drawDecoration(d)}const drawables=[];for(const o of obstacles){if(worldVisible(o.x,o.y,Math.max(100,(o.r||40)*2.4)))drawables.push({y:o.y,fn:()=>drawObstacle(o)})}for(const e of enemies)if(!e.dead&&worldVisible(e.x,e.y,100))drawables.push({y:e.y,fn:()=>drawPoke(e,false)});for(const e of corpses)if(!e.dead&&worldVisible(e.x,e.y,100))drawables.push({y:e.y,fn:()=>drawPoke(e,false)});if(raidSession?.mode==='group')for(const [i,u] of raidSession.supportUnits.entries()){u.x=player.x+Math.cos(elapsed*1.1+i*6.283/raidSession.supportUnits.length)*82;u.y=player.y+Math.sin(elapsed*1.1+i*6.283/raidSession.supportUnits.length)*56+18;drawables.push({y:u.y,fn:()=>drawPoke(u,true)})}drawables.push({y:player.y,fn:()=>drawPoke(player,true)});drawables.sort((a,b)=>a.y-b.y);for(const d of drawables)d.fn();drawEffects();ctx.restore();ctx.restore();}
function loop(ts){if(!running)return;const dt=Math.min(.04,Math.max(.001,(ts-last)/1000||.016));last=ts;update(dt);if(ts-lastHud>=100){updateHud();lastHud=ts}if(ts-lastClock>=1000){updateRaidClock();lastClock=ts}const renderInterval=cv.clientWidth<760?1000/24:1000/30;if(!lastRender||ts-lastRender>=renderInterval){render();lastRender=ts}raf=requestAnimationFrame(loop)}
function pointerWorld(ev){const r=cv.getBoundingClientRect();return{x:cam.x+(ev.clientX-r.left)/CAMERA_ZOOM,y:cam.y+(ev.clientY-r.top)/CAMERA_ZOOM}}
function onKeyDown(e){if(e.target?.closest?.('input,select,textarea,[contenteditable=true]'))return;const k=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','w','a','s','d'].includes(k)){keys.add(k);manualUntil=Date.now()+1600;e.preventDefault()}}
function onKeyUp(e){const k=e.key.length===1?e.key.toLowerCase():e.key;keys.delete(k)}
function onPointer(e){if(e.target!==cv)return;const at=pointerWorld(e);let selected=null,nearest=75*75;for(const mon of [...corpses,...enemies]){if(mon.dead)continue;const d=dist2(at,mon);if(d<nearest){nearest=d;selected=mon}}if(selected){player.target=selected;pointerTarget=null;manualUntil=Date.now()+1200;notify(`Alvo selecionado: ${selected.name} Lv.${selected.level}.`);return}pointerTarget=at;manualUntil=Date.now()+1800}

